import { Fragment } from 'react';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { ToggleTokenBalanceVisibility } from '~/features/toggle-switches/ui/toggle-token-balance-visiblity';
import { BiometricRegister } from '~/entities/biometric/ui/biometric-register';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { VerificationType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';
import { ToggleSwitchSection } from '~/shared/ui/toggle-switch/toggle-switch-section';

export const SecurityPage = () => {
  useSetHeaderTitle(i18n.t('authenticationAndSecurity'));
  const { navigate } = useNavigate();
  const { data: userRes } = useGetUserInfoQuery();
  return (
    <Fragment>
      <div className="menu-box">
        <button
          type="button"
          className="menu-btn"
          onClick={() =>
            navigate(PATHS.mobileVerification, {
              state: { ...userRes.tbCstmrMastr, verificationType: VerificationType.ReSetUser },
            })
          }
        >
          <span className="menu-btn-text">{i18n.t('resetPin')}</span>
        </button>
        <BiometricRegister />
      </div>
      <ToggleSwitchSection label={i18n.t('hideTokenBalance')} desc={i18n.t('text:hideBalanceDescription')}>
        <ToggleTokenBalanceVisibility />
      </ToggleSwitchSection>
    </Fragment>
  );
};
